/**
 * Translation Type Generator
 *
 * Auto-generates TypeScript types for all translation keys from JSON files.
 * This provides compile-time type safety for translation keys.
 *
 * Run with: npm run generate:i18n-types
 *
 * `★ Insight ─────────────────────────────────────`
 * **Why this matters**: Translation keys are normally unchecked strings.
 * A typo like `t('settings.ruls')` would fail silently at runtime, showing
 * the key name or fallback string to the user. With auto-generated types,
 * TypeScript catches these errors at compile time, providing immediate
 * feedback in your editor.
 * `─────────────────────────────────────────────────`
 */

import { readFileSync, writeFileSync, readdirSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

interface TranslationObject {
  [key: string]: string | TranslationObject;
}

/**
 * Recursively extracts all translation keys from a nested object
 * @param obj - The translation object to extract keys from
 * @param prefix - The current key prefix (for nested keys)
 * @returns Array of all translation keys in dot-notation
 */
function extractKeys(obj: TranslationObject, prefix = ''): string[] {
  const keys: string[] = [];

  for (const [key, value] of Object.entries(obj)) {
    const fullKey = prefix ? `${prefix}.${key}` : key;

    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
      // Recurse into nested objects
      keys.push(...extractKeys(value, fullKey));
    } else {
      // Leaf node - this is a translation key
      keys.push(fullKey);
    }
  }

  return keys;
}

/**
 * Generates PascalCase type name from namespace
 */
function toTypeName(namespace: string): string {
  return `${namespace.charAt(0).toUpperCase() + namespace.slice(1)}TranslationKeys`;
}

/**
 * Main generation function
 */
function generateTypes() {
  // Paths
  const localesDir = join(__dirname, '../src/i18n/locales/en');
  const outputPath = join(__dirname, '../src/i18n/types.ts');
  const hooksPath = join(__dirname, '../src/shared/hooks/useGameTranslations.ts');

  // Get all namespace files (excluding .DS_Store)
  const namespaces = readdirSync(localesDir)
    .filter(f => f.endsWith('.json'))
    .map(f => f.replace('.json', ''));

  console.log(`Found ${namespaces.length} namespaces: ${namespaces.join(', ')}`);

  // Generate type definitions
  let output = '// Auto-generated from translation files - do not edit\n';
  output += '// Generated by: scripts/generateTranslationTypes.ts\n';
  output += '// Run "npm run generate:i18n-types" to regenerate\n\n';
  output += '/**\n';
  output += ' * Type-safe translation keys\n';
  output += ' * \n';
  output += ' * Provides compile-time type checking for translation keys.\n';
  output += ' * Typos in translation keys will now be caught at compile time.\n';
  output += ' * \n';
  output += ' * @example\n';
  output += ' * ```ts\n';
  output += ' * import type { CommonTranslationKeys } from "@/i18n/types";\n';
  output += ' * \n';
  output += ' * const key: CommonTranslationKeys = "settings.title"; // ✅ Valid\n';
  output += ' * const bad: CommonTranslationKeys = "settings.titl"; // ❌ TypeScript error\n';
  output += ' * ```\n';
  output += ' */\n\n';

  // Generate types for each namespace
  for (const ns of namespaces) {
    const filePath = join(localesDir, `${ns}.json`);
    const translations: TranslationObject = JSON.parse(readFileSync(filePath, 'utf-8'));
    const keys = extractKeys(translations);

    const typeName = toTypeName(ns);

    output += `export type ${typeName} =\n`;
    output += keys.map(k => `  | '${k}'`).join('\n');
    output += ';\n\n';

    console.log(`  ${ns}: ${keys.length} keys`);
  }

  // Write types file
  writeFileSync(outputPath, output);
  console.log(`\n✓ Types written to: ${outputPath}`);

  // Update the useGameTranslations.ts file to use the generated types
  console.log(`\nUpdating ${hooksPath}...`);
  let hooksContent = readFileSync(hooksPath, 'utf-8');

  // Replace the placeholder types with actual import
  const placeholderStart = '// Placeholder types - these will be auto-generated';
  const placeholderEnd = 'export interface ShapeArchitectTranslationKeys extends Record<string, unknown> {}';

  const typeImports = namespaces.map(ns => `  | ${toTypeName(ns)}`).join('\n');

  const newTypesSection = `// Import auto-generated translation types
import type {
${namespaces.map(ns => `  ${toTypeName(ns)}`).join(',\n')}
} from '@/i18n/types';

/**
 * Union type of all translation keys across all namespaces
 * Useful for generic translation utilities
 */
export type TranslationKeys =
${typeImports};
`;

  // Replace the placeholder section
  const placeholderRegex = /\/\/ Placeholder types - these will be auto-generated[\s\S]*?export interface ShapeArchitectTranslationKeys extends Record<string, unknown> \{\}/;
  hooksContent = hooksContent.replace(placeholderRegex, newTypesSection.trim());

  writeFileSync(hooksPath, hooksContent);
  console.log(`✓ Updated: ${hooksPath}`);

  console.log('\n✅ Translation type generation complete!');
  console.log('\nNext steps:');
  console.log('  1. Check for any TypeScript errors');
  console.log('  2. Test autocomplete in your IDE');
  console.log('  3. Run "npm run build" to verify types work correctly');
}

// Run generation
try {
  generateTypes();
} catch (err) {
  console.error('Error generating translation types:', err);
  process.exit(1);
}
